css:
@font-face {
	font-family: "THSarabun";
	src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}
@page {
	size: A4 portrait;
	margin: 0;
}
* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}
html,
body {
	margin: 0;
	padding: 0;
}
body {
	font-family:
		"Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial,
		sans-serif;
	font-size: 9pt;
	color: #111;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	min-height: unset !important;
	max-width: unset !important;
}
.print-format-preview {
	padding: 0 !important;
}
.page {
	width: 210mm;
	height: 297mm;
	position: relative;
	overflow: hidden;
	page-break-after: always;
	background-size: 210mm 297mm;
	background-repeat: no-repeat;
	font-family: "THSarabun", "Sarabun", Arial, sans-serif;
	font-size: 12pt;
	color: #111;
}
.page:last-child {
	page-break-after: auto;
}
.f {
	position: absolute;
	line-height: 1.08;
	white-space: normal;
}

.field {
	position: absolute;
	line-height: 1.08;
	white-space: nowrap;
}
.text-right {
	text-align: right;
}
.amount {
	text-align: right;
	font-variant-numeric: tabular-nums;
	white-space: nowrap;
}
.tr {
	text-align: right;
}
.tc {
	text-align: center;
}
.nowrap {
	white-space: nowrap;
	overflow: hidden;
}
.small {
	font-size: 10.5pt;
}
.items table {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}
.items td {
	padding: 0.8mm 1mm;
	vertical-align: top;
	line-height: 1.05;
}

.page {
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/pm_omron.webp");
}

.customer-name {
	top: 53.5mm;
	left: 54mm;
	width: 84mm;
	font-size: 11pt;
}
.pm-date {
	top: 54mm;
	left: 171mm;
	width: 33mm;
	font-size: 11pt;
}
.equipment-type {
	top: 61.5mm;
	left: 54mm;
	width: 84mm;
	font-size: 11pt;
}
.manufacturer {
	top: 61.5mm;
	left: 171mm;
	width: 33mm;
	font-size: 11pt;
}
.serial-no {
	top: 69.5mm;
	left: 54mm;
	width: 84mm;
	font-size: 11pt;
}
.model {
	top: 68mm;
	left: 171mm;
	width: 33mm;
	font-size: 11pt;
}
.remark {
	top: 237mm;
	left: 16mm;
	width: 178mm;
	font-size: 10pt;
	line-height: 1.2;
}
.engineer {
	top: 251.5mm;
	left: 56mm;
	width: 50mm;
	text-align: center;
}
/* Match prototype print weight for ERP-filled text. */
.f,
.field,
.items,
.items td,
.amount-words,
.small,
.medium,
.big,
.customer-name,
.pm-date,
.equipment-type,
.manufacturer,
.serial-no,
.model,
.remark,
.engineer {
	font-weight: 700;
}
